# owner: platform
from typing import Dict, List

from hourglass.schedule import worker_minutes
from hourglass.models import Shift
from collections import Counter


def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts given")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("blank worker name")


def _line(name: str, count: int, minutes: int) -> str:
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} hours"


def _ranked(totals: Dict[str, int]) -> List[str]:
    def rank(name: str) -> tuple:
        return (-totals[name], name)
    return sorted(totals, key=rank)


def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker, most hours first."""
    _check(shifts)
    totals = worker_minutes(shifts)
    counts = Counter(shift.worker for shift in shifts)
    return [_line(name, counts[name], totals[name])
            for name in _ranked(totals)]

